settings.custom_css:
.scroll-left{
    opacity: 0;
    transition: 0.5s all;
    transform: translate3d(-30px, 0, 0);
}

.scroll-right{
    opacity: 0;
    transition: 0.5s all;
    transform: translate3d(30px, 0, 0);
}

.scroll-bottom{
    opacity: 0;
    transition: 0.5s all;
    transform: translate3d(0, 80px, 0);
}

.scroll-top{
    opacity: 0;
    transition: 0.5s all;
    transform: translate3d(0, -80px, 0);
}

.ativo{
		opacity: 1;
    transition: 0.5s all;
    transform: translate3d(0, 0, 0);
}

selector{
    position: absolute;
    bottom:80px;
    right:-40px;
}

@media (max-width:768px){
    selector{
    position: absolute;
    bottom:50px;
    right:0px;
}
}

page_settings.custom_css:
::selection {
    background-color: rgba(255, 255, 255, 0.125);
}

html, body {
    overflow-x: hidden;
}

p:last-of-type {
    margin-bottom: 0;
}

body::-webkit-scrollbar {
    width: 10px; /* largura da barra de rolagem */
}

body::-webkit-scrollbar-track {
    background-color: #111111; /* cor da área de rastreamento */
}

body::-webkit-scrollbar-thumb {
    background: linear-gradient(90deg, #fff, #fff); /* cor do SCROLL*/
    border-radius: 15px; /* arredondamento do SCROLL */
    border: 2px solid #111111; /* cria espaçamento em torno do SCROLL*/
}

html {
    scroll-behavior: auto !important; /* Desativa o smooth scroll nativo para evitar conflitos */
}
